    def is_gp(seq):
        m = len(seq)
        if m <= 2:
            return True

        # Check if all zeros
        if all(x == 0 for x in seq):
            return True

        first_zero_first = seq[0] == 0
        if first_zero_first:
            # If first is 0, all must be 0
            return all(x == 0 for x in seq)

        # For GP, seq[i] * seq[0] should equal seq[0] * (seq[1]/seq[0])^i
        # Check seq[i+1] * seq[0] == seq[i] * seq[1] for i >= 1
        # Actually just check the ratio consistency
        r_num = seq[1]
        r_den = seq[0]

        # For each i from 1 to m-2, check: seq[i+2] * r_den * seq[1] == seq[i+1] * r_num * seq[0]
        # Simplified: seq[i+1] * r_num == seq[i+2] * r_den

        for i in range(1, m - 1):
            if seq[i+1] * r_den != seq[i+2] * r_num:
                return False

        return True

    # Check if already GP
    if is_gp(arr):
        return "0\n"

    # Try removing each element
    for i in range(n):
        new_arr = arr[:i] + arr[i+1:]
        if is_gp(new_arr):
            return "1\n"

    return "2\n"

