class SegmentTree:
    def __init__(self, size):
        self.n = size
        # 1-indexed segment tree, max nodes = 4*size
        self.tree = [0] * (4 * size + 1)
        self.lazy = [0] * (4 * size + 1)

    def push(self, node):
        if self.lazy[node]:
            self.lazy[2 * node] = self.lazy[node]
            self.lazy[2 * node + 1] = self.lazy[node]
            self.tree[2 * node] = 1
            self.tree[2 * node + 1] = 1
            self.lazy[node] = 0

    def update(self, node, start, end, l, r):
        if r < start or end < l:
            return
        if l <= start and end <= r:
            self.tree[node] = 1
            self.lazy[node] = 1
            return
        self.push(node)
        mid = (start + end) // 2
        self.update(2 * node, start, mid, l, r)
        self.update(2 * node + 1, mid + 1, end, l, r)
        self.tree[node] = max(self.tree[2 * node], self.tree[2 * node + 1])

    def query(self, node, start, end, l, r):
        if r < start or end < l:
            return 0
        if l <= start and end <= r:
            return self.tree[node]
        self.push(node)
        mid = (start + end) // 2
        return max(self.query(2 * node, start, mid, l, r),
                   self.query(2 * node + 1, mid + 1, end, l, r))

    def mark_range(self, l, r):
        self.update(1, 1, self.n, l, r)

    def has_occupied(self, l, r):
        return self.query(1, 1, self.n, l, r) > 0


