def count_char_in_substrings(s: str) -> List[int]:
    """Count occurrences of each character in all substrings of s.
    Returns list of size 26 where idx represents character."""
    count = [0] * 26
    for i in range(len(s)):
        for j in range(i, len(s)):
            for k in range(j - i + 1):
                if s[j-k] in 'abcdefghijklmnopqrstuvwxyz':
                    count[ord(s[j-k]) - ord('a')] += 1
    return count

