def compute_min_cost_per_dwarf(dwarf, stations, target_x, target_y):
    # Cost for this dwarf to reach (target_x, target_y)
    # Option 1: Walk directly
    direct = abs(dwarf[0] - target_x) + abs(dwarf[1] - target_y)

    # Option 2: Use subway
    if not stations:
        return direct

    # Find min cost to reach gathering point via subway
    min_via_subway = float('inf')
    for station in stations:
        cost = (abs(station[0] - dwarf[0]) + abs(station[1] - dwarf[1])) + abs(station[0] - target_x) + abs(station[1] - target_y)
        min_via_subway = min(min_via_subway, cost)

    return min(direct, min_via_subway)

def compute_max_cost(dwarves, stations, target_x, target_y):
    if not dwarves:
        return 0

    max_cost = 0
    for dwarf in dwarves:
        cost = compute_min_cost_per_dwarf(dwarf, stations, target_x, target_y)
        max_cost = max(max_cost, cost)

    return max_cost

