def solution(input_str):
    from collections import deque

    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return '0\n'

    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # Build adjacency list for good pairs
    adj = [[] for _ in range(n)]
    for i in range(m):
        i1, j1 = map(int, lines[2 + i].split())
        adj[i1 - 1].append(j1 - 1)
        adj[j1 - 1].append(i1 - 1)

    # Count prime factors for each number
    def get_prime_factors(num):
        factors = {}
        d = 2
        temp = num
        while d * d <= temp:
            while temp % d == 0:
                factors[d] = factors.get(d, 0) + 1
                temp //= d
            d += 1
        if temp > 1:
            factors[temp] = factors.get(temp, 0) + 1
        return factors

    prime_counts = [get_prime_factors(a[i]) for i in range(n)]
    all_primes = set()
    for factors in prime_counts:
        all_primes.update(factors.keys())

    INF = float('inf')

    # Dinic's max flow algorithm
    def dinic_max_flow(n_nodes, capacity, s, t):
        flow = 0
        while True:
            level = [-1] * n_nodes
            level[s] = 0
            queue = deque([s])
            while queue:
                u = queue.popleft()
                for v in range(n_nodes):
                    if capacity[u][v] > 0 and level[v] < 0:
                        level[v] = level[u] + 1
                        queue.append(v)
            if level[t] < 0:
                break
            ptr = [0] * n_nodes

            def dfs(u, pushed):
                if pushed == 0 or u == t:
                    return pushed
                for v in range(ptr[u], n_nodes):
                    ptr[u] = v
                    if level[v] == level[u] + 1 and capacity[u][v] > 0:
                        tr = dfs(v, min(pushed, capacity[u][v]))
                        if tr == 0:
                            continue
                        capacity[u][v] -= tr
                        capacity[v][u] += tr
                        return tr
                return 0

            while True:
                pushed = dfs(s, INF)
                if pushed == 0:
                    break
                flow += pushed
        return flow

    total_operations = 0

    for p in all_primes:
        cnts = [prime_counts[i].get(p, 0) for i in range(n)]

        n_nodes = n + 2
        source = n
        sink = n + 1

        cap = [[0] * n_nodes for _ in range(n_nodes)]
        for i in range(n):
            if i % 2 == 0:  # 0-indexed even -> 1-indexed odd
                cap[source][i] = cnts[i]
            else:  # 0-indexed odd -> 1-indexed even
                cap[i][sink] = cnts[i]

        for i in range(n):
            for j in adj[i]:
                if i < j:
                    cap[i][j + n_nodes] = INF
                    cap[j + n_nodes][i] = INF

        flow = dinic_max_flow(n_nodes, cap, source, sink)
        total_operations += flow

    return str(total_operations) + '\n'

