def nCr(n: int, r: int) -> int:
    """Calculate n choose r"""
    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1
    if r > n // 2:
        r = n - r

    result = 1
    for i in range(r):
        result = result * (n - i) // (i + 1)
    return result

