            m = max_m
        else:
            m = int((w - a * target_x) / (a + target_x))
            if m < 1:
                continue

        # Check if m is valid
        if m >= 1 and m <= max_m:
            # Check if both dimensions give same or compatible x
            x_from_m = (w - m * a) / (m + 1)
